g_phase3_format_metric($eng)?></td><td><?=marketing_phase3_format_metric($engRate,'percent')?></td><td><?=marketing_phase3_format_metric($m['impressions'])?></td><td><?=marketing_phase3_format_metric($m['link_clicks'])?></td><td><?=marketing_phase3_format_metric($ctr,'percent')?></td><td><?=marketing_phase3_format_metric($m['spend'],'money')?></td><td><?=marketing_phase3_format_metric($cpc,'money')?></td><td><?=marketing_phase3_format_metric($cpm,'money')?></td><td><?=marketing_phase3_format_metric($metricRevenue,'money')?></td><td><?=marketing_phase3_format_metric($metricRoas,'ratio')?></td><td><span class="marketing-source-badge"><?=marketing_e($sources[$m['source_type']]??$m['source_type'])?></span><?php if(!(int)$m['is_valid']):?><span class="marketing-source-badge">Corrected history</span><?php endif;?><small><?=marketing_e((string)$m['entered_by_name'])?> · <?=marketing_e((string)$m['entered_at'])?></small></td><td><?=$m['evidence_file']?'<a class="marketing-link" href="'.BASE_URL.'/apps/marketing/metric-file.php?id='.(int)$m['id'].'">View</a>':'—'?></td></tr><?php endforeach;?><?php if(!$campaignMetrics):?><tr><td colspan="15" class="marketing-empty">No performance snapshot for this campaign. Calculated rates remain unavailable until their source values exist.</td></tr><?php endif;?></tbody></table></div><p class="marketing-safe-note"><i data-lucide="calculator"></i> Engagement rate, CTR, CPC, CPM and ROAS are calculated by the portal only when the required denominator exists. ROAS is not profit.</p></section>
